add(325,'single','Постройте треугольник по стороне, высоте к ней и медиане к одной из двух других сторон.','Пусть известны BC = a, AH = h, BM = m. M строится на параллельной BC на расстоянии h/2 и на окружности (B,m); A — отражение C относительно M.',[row('Как связать высоту и середину AC?','Обозначим данную сторону BC, высоту AH, медиану BM к AC. Если M — середина AC, её расстояние до BC равно половине AH. Используем это для построения, а затем докажем.','Поиск вспомогательного условия',[17,37]),row('Как найти M?','Отложим BC. Разделим h пополам и проведём по выбранную сторону BC параллельную на расстоянии h/2. Пересечём её с окружностью с центром B радиуса m. Каждая точка пересечения — кандидат M.','Построения расстояния и окружности',[21,23,37]),row('Как получить вершину A?','Продолжим CM за M и отложим MA = MC. Соединим A с B. Тогда M — середина AC и BM — медиана заданной длины.','Определение медианы',[17]),row('Как доказать высоту h без подобия?','Опустим MK ⟂ BC. Если K совпадает с C, то AC ⟂ BC и AC = 2MC = 2MK = h: высота из A имеет нужную длину. Если K ≠ C, продолжим KM за M до N так, чтобы MN = MK. Невырожденные треугольники CMK и AMN равны по двум сторонам и вертикальному углу. Поэтому AN ⟂ KN, откуда AN ∥ BC. Прямая AN находится над BC на расстоянии KN = 2MK = h; значит, высота AH = h.','Первый признак; параллельность и расстояние',[15,25,37]),row('Когда и сколько положений возможно?','Если m < h/2, окружность не достигает параллельной — решений нет. При m = h/2 одна точка M в выбранной полуплоскости; при m > h/2 две. Для каждой строим свою A; отражения по другую сторону BC дают зеркальные размещения.','Перпендикуляр и наклонная; пересечение окружности с прямой',[37])],p,v0,[v0,v2,v3,v4,v3],checks=[equal(('A','M'),('M','C')),col('A','M','C'),equal(('M','K'),('M','N')),col('K','M','N'),par('A','N','B','C'),perp('M','K','B','C'),ratio('A','H','M','K',2),equal(('B','M'),('B','M1')),equal(('A1','M1'),('M1','C')),equal(('A2','M2'),('M2','C')),perp('A1','H1','B','C'),ratio('A2','H2','B','M2',2),col('A3','M3','C3'),equal(('A3','M3'),('M3','C3')),perp('A3','C3','B','C3'),ratio('A3','C3','M3','C3',2)],cases=[case(v4,'Почему высота удваивается',4),case(alt,'Второе положение при m > h/2',5),case(boundary,'Если m = h/2',5),case(rightcase,'Если K совпадает с C',4)],labels={'A1':'A','M1':'M','H1':'H','A2':'A','M2':'M','H2':'H','A3':'A','M3':'M','C3':'C'})
